import { test, expect } from '@playwright/test';

test.describe('1. Админ-панель — матрица прав и спец. действия', () => {
  test('1.9 Гость на /admin перенаправляется на вход @desktop @prod-safe (#6a8a96c821e5a64ca7a411dd)', async ({ page }) => {
    // 1. Открыть `/admin`.
    await page.goto('/admin');
    await expect(page).toHaveURL(/\/(welcome|sign-in)/);
    await expect(page.getByText(/Continue with Email|Sign in|המשך עם אימייל|התחברות/).first()).toBeVisible();
    await expect(page.getByText(/Audit log|יומן ביקורת/)).toHaveCount(0);

    // 2. Открыть `/admin/users`.
    await page.goto('/admin/users');
    await expect(page).toHaveURL(/\/(welcome|sign-in)/);
    await expect(page.getByText(/Continue with Email|Sign in|המשך עם אימייל|התחברות/).first()).toBeVisible();
    await expect(page.getByText(/Audit log|יומן ביקורת/)).toHaveCount(0);
    await expect(page.getByRole('table')).toHaveCount(0);
  });
});
